<template><div class="app-container"><el-card><template #header><b>合伙人数据统计</b><el-button style="float:right" @click="load">刷新</el-button></template><el-row :gutter="16"><el-col v-for="item in data.summary||[]" :key="item.status" :span="6"><el-statistic :title="item.status" :value="item.count"/></el-col></el-row></el-card><el-card style="margin-top:16px"><el-table :data="data.partners||[]" stripe><el-table-column prop="customerId" label="会员ID"/><el-table-column prop="nickname" label="合伙人"/><el-table-column prop="phone" label="手机"/><el-table-column prop="partnerStatus" label="状态"/><el-table-column prop="customerCount" label="客户数"/><el-table-column prop="orderCount" label="有效订单"/><el-table-column prop="salesAmount" label="有效销售额"><template #default="s">¥{{s.row.salesAmount}}</template></el-table-column></el-table></el-card><el-card style="margin-top:16px"><template #header><b>客户归属关系</b></template><el-table :data="owners" stripe><el-table-column prop="customerId" label="客户ID"/><el-table-column prop="nickname" label="客户"/><el-table-column prop="phone" label="手机"/><el-table-column prop="ownerId" label="合伙人ID"/><el-table-column prop="ownerName" label="归属合伙人"/><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="openOwner(s.row)">调整归属</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="dialog" title="调整客户归属" width="480px"><el-form label-position="top"><el-form-item label="客户"><el-input :model-value="`${ownerForm.nickname}（${ownerForm.customerId}）`" disabled/></el-form-item><el-form-item label="新合伙人会员ID"><el-input-number v-model="ownerForm.ownerId" :min="1" style="width:100%"/></el-form-item><el-form-item label="调整原因"><el-input v-model="ownerForm.reason" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="saveOwner">确认并记录</el-button></template></el-dialog></div></template>
<script setup>import { ElMessage } from 'element-plus';import request from '@/utils/request';const data=ref({summary:[],partners:[]});const owners=ref([]);const dialog=ref(false);const ownerForm=ref({});async function load(){data.value=(await request({url:'/mall/admin/partner/stats',method:'get'})).data||{};owners.value=(await request({url:'/mall/admin/partner/customers',method:'get'})).data||[]}function openOwner(row){ownerForm.value={...row,reason:''};dialog.value=true}async function saveOwner(){if(!ownerForm.value.ownerId||!ownerForm.value.reason?.trim())return ElMessage.warning('请选择新合伙人并填写调整原因');await request({url:`/mall/admin/partner/customers/${ownerForm.value.customerId}/owner`,method:'put',data:{ownerId:ownerForm.value.ownerId,reason:ownerForm.value.reason}});ElMessage.success('归属已调整并写入记录');dialog.value=false;load()}onMounted(load)</script>
